contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable {
        uint256 balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cEtherBefore = address(c).balance;

        bool reverted;
        c.Collect(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cEtherAfter = address(c).balance;

        assert(reverted || (balAfter <= balBefore && cEtherAfter <= cEtherBefore));
    }

    receive() external payable {}
}

